import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv_transpose3d_fwd(
    .param .u64 _in_ptr,
    .param .u64 _w_ptr,
    .param .u64 _out_ptr,
    .param .u32 _total,
    .param .u32 _ic,
    .param .u32 _oc,
    .param .u32 _inD,
    .param .u32 _outD,
    .param .u32 _k
)
{
    .reg .pred  %p<8>;
    .reg .b32   %r<40>;
    .reg .b64   %rd<8>;
    .reg .f32   %f<8>;

    ld.param.u64 %rd0, [_in_ptr];
    ld.param.u64 %rd1, [_w_ptr];
    ld.param.u64 %rd2, [_out_ptr];
    ld.param.u32 %r0,  [_total];
    ld.param.u32 %r8,  [_ic];
    ld.param.u32 %r9,  [_oc];
    ld.param.u32 %r10, [_inD];
    ld.param.u32 %r11, [_outD];
    ld.param.u32 %r12, [_k];

    // global linear thread id
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r1, %r1, %r2, %r3;      // r1 = tid

    setp.ge.u32 %p0, %r1, %r0;
    @%p0 bra L_DONE;

    // decode tid -> (n, oc, d, h, w), w fastest
    rem.u32 %r2, %r1, %r11;             // w
    div.u32 %r3, %r1, %r11;
    rem.u32 %r4, %r3, %r11;             // h
    div.u32 %r3, %r3, %r11;
    rem.u32 %r5, %r3, %r11;             // d
    div.u32 %r3, %r3, %r11;
    rem.u32 %r6, %r3, %r9;              // oc
    div.u32 %r7, %r3, %r9;              // n

    mul.lo.u32 %r23, %r10, %r10;        // inD^2
    mul.lo.u32 %r24, %r23, %r10;        // inD^3
    mul.lo.u32 %r25, %r12, %r12;        // k^2
    mul.lo.u32 %r26, %r25, %r12;        // k^3

    mov.f32 %f0, 0f00000000;            // accumulator
    mov.u32 %r13, 0;                    // ic

L_IC_LOOP:
    setp.ge.u32 %p1, %r13, %r8;
    @%p1 bra L_IC_DONE;

    // input base = (n*IC + ic) * inD^3
    mul.lo.u32 %r21, %r7, %r8;
    add.u32 %r21, %r21, %r13;
    mul.lo.u32 %r21, %r21, %r24;

    // weight base = (ic*OC + oc) * k^3
    mul.lo.u32 %r22, %r13, %r9;
    add.u32 %r22, %r22, %r6;
    mul.lo.u32 %r22, %r22, %r26;

    mov.u32 %r14, 0;                    // kd
L_KD_LOOP:
    setp.ge.u32 %p2, %r14, %r12;
    @%p2 bra L_KD_DONE;
    sub.s32 %r17, %r5, %r14;            // id = d - kd
    setp.lt.s32 %p3, %r17, 0;
    @%p3 bra L_KD_NEXT;
    setp.ge.s32 %p4, %r17, %r10;
    @%p4 bra L_KD_NEXT;

    mov.u32 %r15, 0;                    // kh
L_KH_LOOP:
    setp.ge.u32 %p2, %r15, %r12;
    @%p2 bra L_KH_DONE;
    sub.s32 %r18, %r4, %r15;            // ih = h - kh
    setp.lt.s32 %p3, %r18, 0;
    @%p3 bra L_KH_NEXT;
    setp.ge.s32 %p4, %r18, %r10;
    @%p4 bra L_KH_NEXT;

    mov.u32 %r16, 0;                    // kw
L_KW_LOOP:
    setp.ge.u32 %p2, %r16, %r12;
    @%p2 bra L_KW_DONE;
    sub.s32 %r19, %r2, %r16;            // iw = w - kw
    setp.lt.s32 %p3, %r19, 0;
    @%p3 bra L_KW_NEXT;
    setp.ge.s32 %p4, %r19, %r10;
    @%p4 bra L_KW_NEXT;

    // input offset = base + id*inD^2 + ih*inD + iw
    mad.lo.u32 %r27, %r17, %r23, %r21;
    mad.lo.u32 %r27, %r18, %r10, %r27;
    add.u32 %r27, %r27, %r19;

    // weight offset = base + kd*k^2 + kh*k + kw
    mad.lo.u32 %r28, %r14, %r25, %r22;
    mad.lo.u32 %r28, %r15, %r12, %r28;
    add.u32 %r28, %r28, %r16;

    mul.wide.u32 %rd3, %r27, 4;
    add.u64 %rd3, %rd0, %rd3;
    ld.global.f32 %f1, [%rd3];

    mul.wide.u32 %rd4, %r28, 4;
    add.u64 %rd4, %rd1, %rd4;
    ld.global.f32 %f2, [%rd4];

    fma.rn.f32 %f0, %f1, %f2, %f0;

L_KW_NEXT:
    add.u32 %r16, %r16, 1;
    bra L_KW_LOOP;
L_KW_DONE:

L_KH_NEXT:
    add.u32 %r15, %r15, 1;
    bra L_KH_LOOP;
L_KH_DONE:

L_KD_NEXT:
    add.u32 %r14, %r14, 1;
    bra L_KD_LOOP;
L_KD_DONE:

    add.u32 %r13, %r13, 1;
    bra L_IC_LOOP;
L_IC_DONE:

    // output offset equals tid (same contiguous layout order)
    mul.wide.u32 %rd5, %r1, 4;
    add.u64 %rd5, %rd2, %rd5;
    st.global.f32 [%rd5], %f0;

L_DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_fwd")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, kernel_size=(kernel_size, kernel_size, kernel_size), stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.conv_transpose3d.weight.contiguous()

        n, ic, d, h, w = x.shape
        oc = self.conv_transpose3d.out_channels
        k = self.conv_transpose3d.kernel_size[0]
        s = self.conv_transpose3d.stride[0]
        p = self.conv_transpose3d.padding[0]
        op = self.conv_transpose3d.output_padding[0]

        out_d = (d - 1) * s - 2 * p + k + op
        out_h = (h - 1) * s - 2 * p + k + op
        out_w = (w - 1) * s - 2 * p + k + op

        out = torch.empty((n, oc, out_d, out_h, out_w), dtype=x.dtype, device=x.device)
        total = out.numel()

        module = _get_ptx_module()
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module.launch(
            "conv_transpose3d_fwd",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, weight, out, u32(total), u32(ic), u32(oc), u32(d), u32(out_d), u32(k)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

