        oc = self.conv_transpose3d.out_channels
        k = self.conv_transpose3d.kernel_size[0]
        s = self.conv_transpose3d.stride[0]
        p = self.conv_transpose3d.padding[0]
        op = self.conv_transpose3d.output_padding[0]

        out_d = (d - 1) * s - 2 * p + k + op
        out_h = (h - 1) * s - 2 * p + k + op
        out_w = (w - 1) * s - 2 * p + k + op

        out = torch.empty((n, oc, out_d, out_h, out_w), dtype=x.dtype, device=x.device)
        total = out.numel()

        module = _get_ptx_module()
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module.launch(
            "conv_transpose3d_fwd",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, weight, out, u32(total), u32(ic), u32(oc), u32(d), u32(out_d), u32(k)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
